// VSZOOMFS_DIAGNOSTIC_BEGIN
public static boolean vsZoomDiagnosticsEnabled() {
    return org.chromium.base.CommandLine.isInitialized()
            && org.chromium.base.CommandLine.getInstance().hasSwitch("versanium-zoom-fullscreen-diagnostics");
}
private static final class VSZoomSample {
    double raw, adjusted, before;
    String slot = "", beforeSlot = "", last = "";
    int tab = -1, samples;
    boolean beforeValid, restorePending, limitReported;
}
private static final class VSZoomStore {
    static final WeakHashMap<WebContents, VSZoomSample> samples = new WeakHashMap<>();
}
private static VSZoomSample vsZoomSample(WebContents wc) {
    return VSZoomStore.samples.computeIfAbsent(wc, ignored -> new VSZoomSample());
}
private static void vsZoomEmit(WebContents wc, VSZoomSample sample, String event, String values) {
    if (!vsZoomDiagnosticsEnabled() || wc == null || wc.isDestroyed()) return;
    String key = event + " " + values;
    if (key.equals(sample.last)) return;
    if (sample.samples >= 128) {
        if (!sample.limitReported) {
            sample.limitReported = true;
            Log.i("VersaniumZoomFS", "VSZOOMFS event=DIAGNOSTIC_LIMIT wc_java=%d", System.identityHashCode(wc));
        }
        return;
    }
    sample.last = key; sample.samples++;
    RenderFrameHost frame = wc.getMainFrame();
    GlobalRenderFrameHostId id = frame == null ? null : frame.getGlobalRenderFrameHostId();
    Log.i("VersaniumZoomFS", "VSZOOMFS event=%s seq_wc=%d tab=%d wc_java=%d wc_main_child=%d wc_main_route=%d %s",
            event, sample.samples, sample.tab, System.identityHashCode(wc), id == null ? -1 : id.childId(),
            id == null ? -1 : id.frameRoutingId(), values);
}
private static void vsZoomState(WebContents wc, String host, Binding binding, double raw, double adjusted) {
    VSZoomSample sample = vsZoomSample(wc);
    sample.raw = raw; sample.adjusted = adjusted;
    sample.slot = binding.lastEnvironment.name() + ":" + host; // Internal comparison only; never logged.
    vsZoomEmit(wc, sample, "ZOOM_STATE", "resolved_user_exp=" + raw + " stored_exp=" + raw
            + " adjusted_exp=" + adjusted + " font_factor=" + binding.lastFont
            + " zoom_environment=" + binding.lastEnvironment.name());
    if (sample.restorePending) {
        vsZoomEmit(wc, sample, "ZOOM_RESTORE", "restore_action=none stored_zoom_unchanged="
                + (sample.beforeValid && sample.beforeSlot.equals(sample.slot)
                    ? Boolean.toString(Double.doubleToRawLongBits(sample.before) == Double.doubleToRawLongBits(raw)) : "unknown")
                + " stored_exp=" + raw + " before_exp=" + sample.before);
        sample.restorePending = false;
    }
}
@SuppressWarnings("deprecation") // Read-only Display.getRealSize for existing Android APIs.
public static void vsZoomFullscreen(WebContents wc, int tabId, boolean entered) {
    if (!vsZoomDiagnosticsEnabled() || wc == null || wc.isDestroyed()) return;
    VSZoomSample sample = vsZoomSample(wc); sample.tab = tabId;
    if (entered) {
        sample.beforeValid = !sample.slot.isEmpty(); sample.before = sample.raw;
        sample.beforeSlot = sample.slot;
    } else { sample.restorePending = true; }
    Activity owner = activity(wc);
    String geometry = "window_px=unknown display_px=unknown";
    if (owner != null && !owner.isDestroyed() && !owner.isFinishing()
            && owner.getWindow() != null && owner.getWindow().getDecorView() != null) {
        android.view.View decor = owner.getWindow().getDecorView();
        geometry = "window_px_w=" + decor.getWidth() + " window_px_h=" + decor.getHeight()
                + " display_id=" + displayId(owner);
        android.hardware.display.DisplayManager manager = (android.hardware.display.DisplayManager)
                owner.getSystemService(Context.DISPLAY_SERVICE);
        android.view.Display display = manager == null ? null : manager.getDisplay(displayId(owner));
        if (display != null) {
            android.graphics.Point size = new android.graphics.Point(); display.getRealSize(size);
            geometry += " display_px_w=" + size.x + " display_px_h=" + size.y;
        }
    }
    vsZoomEmit(wc, sample, entered ? "FULLSCREEN_ENTER" : "FULLSCREEN_EXIT",
            "source=java_observer stored_exp=" + sample.raw + " stored_value_stage=last_calculation before_valid=" + sample.beforeValid + " " + geometry);
}
